fn test() -> io::Result<()> {
    let cap = 1000;
    let mut f = File::open("foo.txt").unwrap();

    // should lint
    let mut data = Vec::with_capacity(20);
    f.read_exact(&mut data).unwrap();

    // should lint
    let mut data2 = Vec::with_capacity(cap);
    f.read_exact(&mut data2)?;

    // should lint
    let mut data3 = Vec::new();
    f.read_exact(&mut data3)?;

    // should lint
    let mut data4 = vec![];
    let _ = f.read(&mut data4)?;

    // should lint
    let _ = {
        let mut data5 = Vec::new();
        f.read(&mut data5)
    };

    // should lint
    let _ = {
        let mut data6: Vec<u8> = Default::default();
        f.read(&mut data6)
    };

    // should not lint
    let mut buf = [0u8; 100];
    f.read(&mut buf)?;

    // should not lint
    let mut empty = vec![];
    let mut data7 = vec![];
    f.read(&mut empty);

    // should not lint
    f.read(&mut data7);

    // should not lint
    let mut data8 = Vec::new();
    data8.resize(100, 0);
    f.read_exact(&mut data8)?;

    // should not lint
    let mut data9 = vec![1, 2, 3];
    f.read_exact(&mut data9)?;

    Ok(())
}

