pub struct RedundantStaticLifetimes {
    msrv: Option<RustcVersion>,
}

impl RedundantStaticLifetimes {
    #[must_use]
    pub fn new(msrv: Option<RustcVersion>) -> Self {
        Self { msrv }
    }
