        if let Some(arg) = qpath_generic_tys(qpath).next();
        if path_def_id(cx, arg) == Some(def_id);
        then {
            span_lint(
                cx,
                OPTION_OPTION,
                hir_ty.span,
                "consider using `Option<T>` instead of `Option<Option<T>>` or a custom \
                                     enum if you need to distinguish all 3 cases",
