            if let ExprKind::Cast(left_expr, ty) = &expr.kind;
            if let TyKind::Ptr(_) = ty.kind;
            if let ExprKind::AddrOf(BorrowKind::Ref, mutability, e) = &left_expr.kind;

            then {
                let core_or_std = if is_no_std_crate(cx) { "core" } else { "std" };
