                    cx,
                    BORROW_AS_PTR,
                    expr.span,
                    "borrow as raw pointer",
                    "try",
                    format!(
                        "{}::ptr::{}!({})",
                        core_or_std,
                        macro_name,
                        snippet_opt(cx, e.span).unwrap()
                    ),
                    Applicability::MachineApplicable,
                );
            }
        }
    }

    extract_msrv_attr!(LateContext);
}
